package com.hbm.machine.custommachine;

import com.google.gson.*;
import com.hbm.fluid.*;
import com.hbm.recipe.generic.*;
import com.mojang.logging.LogUtils;
import com.mojang.serialization.JsonOps;
import java.nio.file.*;
import java.util.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.item.crafting.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.nbt.CompoundTag;
import net.neoforged.bus.api.EventPriority;
import net.neoforged.fml.loading.FMLPaths;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.OnDatapackSyncEvent;
import net.neoforged.neoforge.event.server.ServerAboutToStartEvent;

/** Sole native RecipeManager owns source replacement sets AND definition-authored ordinary shaped crafts. */
public final class CustomMachineRecipes {
    private static final Map<String,String> ALIASES=new LinkedHashMap<>();
    private static final Map<RecipeManager,Map<ResourceLocation,RecipeHolder<?>>> INSTALLED=new WeakHashMap<>();
    private static final List<String> UNRESOLVED=new ArrayList<>();
    public static void register(){try(var input=CustomMachineRecipes.class.getResourceAsStream("/hbm/custom-machine114-item-aliases.json")){if(input==null)throw new IllegalStateException("Missing actual custom-machine source aliases");JsonParser.parseReader(new java.io.InputStreamReader(input,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().entrySet().forEach(e->ALIASES.put(e.getKey(),e.getValue().getAsString()));}catch(java.io.IOException error){throw new IllegalStateException(error);}NeoForge.EVENT_BUS.addListener((ServerAboutToStartEvent e)->install(e.getServer()));NeoForge.EVENT_BUS.addListener(EventPriority.LOWEST,(OnDatapackSyncEvent e)->{var server=e.getPlayerList().getServer();if(e.getPlayer()==null||!INSTALLED.containsKey(server.getRecipeManager()))install(server);if(e.getPlayer()==null)server.getPlayerList().getPlayers().forEach(CustomMachineNetwork::send);else CustomMachineNetwork.send(e.getPlayer());});}
    public static String alias(String name){return ALIASES.getOrDefault(name,name);}
    public static List<String> unresolved(){return List.copyOf(UNRESOLVED);}
    public static List<CustomMachineRecipe> recipes(RecipeManager manager,String key){return manager.getAllRecipesFor(CustomMachineContent.TYPE.get()).stream().map(RecipeHolder::value).filter(r->r.recipeKey().equals(key)).sorted(Comparator.comparingInt(r->r.data().order())).toList();}
    public static List<CustomMachineRecipe> recipes(RecipeManager manager){return manager.getAllRecipesFor(CustomMachineContent.TYPE.get()).stream().map(RecipeHolder::value).sorted(Comparator.comparingInt(r->r.data().order())).toList();}
    private static JsonObject resource(String path)throws java.io.IOException{try(var input=CustomMachineRecipes.class.getResourceAsStream(path)){if(input==null)throw new IllegalStateException("Missing source custom-machine resource "+path);return JsonParser.parseReader(new java.io.InputStreamReader(input,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();}}
    private static List<FluidStack> fluids(JsonArray array){var result=new ArrayList<FluidStack>();for(var element:array){var row=element.getAsJsonArray();var type=HbmFluids.fromName(row.get(0).getAsString());if(type==HbmFluids.NONE&&!row.get(0).getAsString().equals("NONE"))throw new IllegalArgumentException("Actual source fluid is not registered: "+row);result.add(new FluidStack(type,row.get(1).getAsInt(),row.size()>2?row.get(2).getAsInt():0));}return result;}
    private static CustomMachineRecipe read(String key,JsonObject row,int order){var inputs=new ArrayList<GenericIngredient>();for(var value:row.getAsJsonArray("inputItems"))inputs.add(GenericRecipeConfigCodec.readIngredient(value.getAsJsonArray(),ALIASES));var outputs=new ArrayList<GenericOutput>();for(var value:row.getAsJsonArray("outputItems")){var array=value.getAsJsonArray();var stack=new JsonArray();for(int i=0;i<array.size()-1;i++)stack.add(array.get(i));outputs.add(new GenericOutput(List.of(new GenericOutput.Chance(GenericRecipeConfigCodec.readStack(stack,ALIASES),array.get(array.size()-1).getAsFloat(),0)),false));}var data=new GenericRecipeData(key+"_"+order,row.get("duration").getAsInt(),row.get("consumptionPerTick").getAsInt(),inputs,fluids(row.getAsJsonArray("inputFluids")),outputs,fluids(row.getAsJsonArray("outputFluids")),List.of(),"",net.minecraft.world.item.ItemStack.EMPTY,false,"",order);boolean hasPollution=row.has("pollutionType")&&row.has("pollutionAmount");return new CustomMachineRecipe(key,data,hasPollution?row.get("pollutionType").getAsString():"",hasPollution?row.get("pollutionAmount").getAsFloat():0,row.has("radiationAmount")?row.get("radiationAmount").getAsFloat():0,row.has("flux")?row.get("flux").getAsInt():0,row.has("heat")?row.get("heat").getAsInt():0);}
    private static void install(MinecraftServer server){var manager=server.getRecipeManager();var previous=INSTALLED.getOrDefault(manager,Map.of());var merged=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();for(var recipe:manager.getOrderedRecipes())if(previous.get(recipe.id())!=recipe)merged.put(recipe.id(),recipe);var additions=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();UNRESOLVED.clear();Path dir=FMLPaths.CONFIGDIR.get().resolve("hbmRecipes"),active=dir.resolve("hbmCustomMachines.json");try{Files.createDirectories(dir);boolean custom=Files.isRegularFile(active);JsonObject root;if(custom){try(var reader=Files.newBufferedReader(active)){root=JsonParser.parseReader(reader).getAsJsonObject();}merged.values().removeIf(h->h.value().getType()==CustomMachineContent.TYPE.get());}else{root=resource("/hbm/custom-machine114-default-recipes.json");Files.writeString(dir.resolve("_hbmCustomMachines.json"),new GsonBuilder().setPrettyPrinting().create().toJson(root)+"\n");}int order=0;for(var group:root.getAsJsonArray("recipes")){var entry=group.getAsJsonObject();String key=entry.get("recipeKey").getAsString();for(var value:entry.getAsJsonArray("recipes")){int index=order++;try{var recipe=read(key,value.getAsJsonObject(),index);var id=ResourceLocation.fromNamespaceAndPath("hbm","custom_machine/"+(custom?"config/":"default/")+index);additions.put(id,new RecipeHolder<>(id,recipe));}catch(Exception error){UNRESOLVED.add("processing "+key+"#"+index+": "+error.getMessage());}}}
        for(int i=0;i<CustomMachinesConfig.niceList.size();i++){var config=CustomMachinesConfig.niceList.get(i);if(!config.json.has("recipeShape")||!config.json.has("recipeParts"))continue;try{var json=new JsonObject();json.add("pattern",config.json.getAsJsonArray("recipeShape").deepCopy());var keys=new JsonObject();var parts=config.json.getAsJsonArray("recipeParts");for(int j=0;j<parts.size();j+=2){var input=GenericRecipeConfigCodec.readIngredient(parts.get(j+1).getAsJsonArray(),ALIASES);keys.add(parts.get(j).getAsString().substring(0,1),Ingredient.CODEC.encodeStart(server.registryAccess().createSerializationContext(JsonOps.INSTANCE),input.ingredient()).getOrThrow());}json.add("key",keys);var stack=CustomMachineContent.controller(100+i);var data=new CompoundTag();data.putString("machineType",config.unlocalizedName);stack.set(DataComponents.CUSTOM_DATA,CustomData.of(data));json.add("result",net.minecraft.world.item.ItemStack.CODEC.encodeStart(server.registryAccess().createSerializationContext(JsonOps.INSTANCE),stack).getOrThrow());var recipe=RecipeSerializer.SHAPED_RECIPE.codec().codec().parse(server.registryAccess().createSerializationContext(JsonOps.INSTANCE),json).getOrThrow();var id=ResourceLocation.fromNamespaceAndPath("hbm","custom_machine/controller/"+i);additions.put(id,new RecipeHolder<>(id,recipe));}catch(Exception error){UNRESOLVED.add("controller "+config.unlocalizedName+": "+error.getMessage());}}
    }catch(Exception error){LogUtils.getLogger().error("Cannot load source custom-machine replacement recipes",error);}additions.forEach(merged::put);manager.replaceRecipes(merged.values());INSTALLED.put(manager,additions);for(var error:UNRESOLVED)LogUtils.getLogger().warn("Unbound actual custom-machine entry: {}",error);}
    private CustomMachineRecipes(){}
}
